/**
 * Normalize a label the way link definitions and references compare it: trimmed, with
 * runs of whitespace collapsed to one space, and lowercased.
 * @param {string} label - the raw label text, between its brackets.
 * @returns {string} the normalized label.
 */
export function normalizeLabel(label) {
  return label.trim().replace(/\s+/gu, ' ').toLowerCase()
}
"}

