{"file_path":"src/block.js","content":"/** Block parsing: fences, headings, nested lists, link definitions, and paragraphs. */

import { renderInline } from './inline.js'
import { normalizeLabel } from './labels.js'

const FENCE = /^(`{3,})([^`]*)$/
const HEADING = /^(#{1,6}) (.*)$/
const ITEM = /^( *)- (.*)$/
const DEFINITION = /^\[([^\]]*)\]:\s+(\S.*)$/u

/** One refusal of a document line, carrying the 1-based line it was read at. */
export class BlockError extends Error {
  /**
   * @param {number} line - the 1-based input line.
   * @param {string} message - the message the specification words, without the position.
   */
  constructor(line, message) {
    super(message)
    this.name = 'BlockError'
    this.line = line
  }
}

/**
 * Every input line, with the empty tail a trailing newline leaves dropped.
 * @param {string} text - the whole input.
 * @returns {string[]} the lines.
 */
export function splitLines(text) {
  const split = text.split('\n')
  if (split.length > 0 && split[split.length - 1] === '') split.pop()
  return split
}

/**
 * Read one link-definition line.
 * @param {string} line - the line, already trimmed.
 * @returns {{label: string, url: string}|undefined} the normalized label and url, or undefined
 *   when the line is not a definition.
 */
export function parseDefinitionLine(line) {
  const match = DEFINITION.exec(line)
  if (match === null) return undefined
  return { label: normalizeLabel(match[1]), url: match[2] }
}

/** Append one item, at its capped level, to the list under construction. */
function addItem(list, level, text) {
  const cap = list.open.length === 0 ? 0 : Math.min(level, list.open.length)
  const node = { text, children: [] }
  if (cap === 0) {
    list.items.push(node)
  } else {
    list.open[cap - 1].children.push(node)
  }
  list.open.length = cap
  list.open.push(node)
}

/**
 * The blocks of one document.
 * @param {string[]} lines - the document's lines.
 * @param {Set<string>} [knownLabels] - normalized labels already defined elsewhere (a
 *   definitions file), so the document may not redefine them.
 * @returns {{blocks: object[], definitions: Map<string, string>}} the blocks in document
 *   order, and the labels the document itself defined.
 * @throws {BlockError} on an unterminated fence or a label defined twice.
 */
export function parse(lines, knownLabels = new Set()) {
  const out = []
  let paragraph = []
  let list
  const known = new Set(knownLabels)
  const definitions = new Map()
  const flush = () => {
    if (paragraph.length > 0) {
      out.push({ kind: 'paragraph', lines: paragraph })
      paragraph = []
    }
    if (list !== undefined) {
      out.push({ kind: 'list', items: list.items })
      list = undefined
    }
  }
  for (let index = 0; index < lines.length; index += 1) {
    const raw = lines[index]
    const line = index + 1
    const fence = FENCE.exec(raw)
    if (fence !== null) {
      flush()
      const content = []
      let close = -1
      for (let scan = index + 1; scan < lines.length; scan += 1) {
        const candidate = lines[scan].trim()
        if (/^`{3,}$/u.test(candidate) && candidate.length >= fence[1].length) {
          close = scan
          break
        }
        content.push(lines[scan])
      }
      if (close === -1) throw new BlockError(line, 'unterminated code fence')
      out.push({ kind: 'fence', info: fence[2].trim().split(/\s+/u)[0], content })
      index = close
      continue
    }
    if (raw.trim() === '') {
      flush()
      continue
    }
    const trimmed = raw.trim()
    const definition = parseDefinitionLine(trimmed)
    if (definition !== undefined) {
      flush()
      if (known.has(definition.label)) throw new BlockError(line, `label ${definition.label} is defined twice`)
      known.add(definition.label)
      definitions.set(definition.label, definition.url)
      continue
    }
    const heading = HEADING.exec(raw)
    if (heading !== null) {
      flush()
      out.push({ kind: 'heading', level: heading[1].length, text: heading[2].trim() })
      continue
    }
    const item = ITEM.exec(raw)
    if (item !== null && paragraph.length === 0) {
      if (list === undefined) list = { items: [], open: [] }
      addItem(list, Math.floor(item[1].length / 2), item[2].trim())
      continue
    }
    if (list !== undefined) flush()
    paragraph.push(trimmed)
  }
  flush()
  return { blocks: out, definitions }
}

/** The lines of one nested list, `<ul>` and `</ul>` included. */
function listLines(items, resolve) {
  const lines = ['<ul>']
  for (const item of items) {
    if (item.children.length === 0) {
      lines.push(`<li>${renderInline(item.text, resolve)}</li>`)
    } else {
      lines.push(`<li>${renderInline(item.text, resolve)}`)
      lines.push(...listLines(item.children, resolve))
      lines.push('</li>')
    }
  }
  lines.push('</ul>')
  return lines
}

/**
 * Render parsed blocks to HTML.
 * @param {readonly object[]} parsed - the document's blocks.
 * @param {(label: string) => string|undefined} [resolve] - resolves a normalized reference
 *   label to its url.
 * @returns {string} the HTML, with a trailing newline unless the document holds no block.
 */
export function render(parsed, resolve = () => undefined) {
  const rendered = parsed.map((block) => {
    if (block.kind === 'heading') return `<h${block.level}>${renderInline(block.text, resolve)}</h${block.level}>`
    if (block.kind === 'paragraph') return `<p>${block.lines.map(text => renderInline(text, resolve)).join('\n')}</p>`
    if (block.kind === 'list') return listLines(block.items, resolve).join('\n')
    const open = block.info === '' ? '<pre><code>' : `<pre><code class="language-${escapeFenceText(block.info)}">`
    return `${open}${block.content.map(text => `${escapeFenceText(text)}\n`).join('')}</code></pre>`
  })
  return rendered.length === 0 ? '' : `${rendered.join('\n')}\n`
}

/** Escape a fence's content or info string: `&`, `<` and `>` only. */
function escapeFenceText(text) {
  return text.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;')
}

/**
 * The headings of parsed blocks, for the outline.
 * @param {readonly object[]} parsed - the document's blocks.
 * @returns {{level: number, text: string}[]} the headings in document order.
 */
export function headings(parsed) {
  return parsed.filter(block => block.kind === 'heading').map(block => ({ level: block.level, text: block.text }))
}
"}

