import { escapeAttribute, escapeText } from './html.js'
import { normalizeLabel } from './labels.js'

const ESCAPABLE = '\\`*[]()'

/** The index of the first `]` that no backslash escapes, or -1. */
function closingBracket(text, from) {
  for (let index = from; index < text.length; index += 1) {
    if (text[index] === '\\') {
      index += 1
      continue
    }
    if (text[index] === ']') return index
  }
  return -1
}

/**
 * One link starting at `[`, or undefined when nothing there is a link: an inline
 * `[text](url)`, or, once that fails, a reference `[text][label]` or `[text][]` that a
 * definition resolves.
 * @param {string} text - the inline text being scanned.
 * @param {number} start - the index of the opening `[`.
 * @param {(label: string) => string|undefined} resolve - resolves a normalized label.
 */
function readLink(text, start, resolve) {
  const close = closingBracket(text, start + 1)
  if (close === -1) return undefined
  const inner = text.slice(start + 1, close)
  if (text[close + 1] === '(') {
    const end = text.indexOf(')', close + 2)
    if (end !== -1) return { url: text.slice(close + 2, end).trim(), inner, next: end + 1 }
  }
  if (text[close + 1] === '[') {
    const labelClose = closingBracket(text, close + 2)
    if (labelClose !== -1) {
      const raw = text.slice(close + 2, labelClose)
      const label = normalizeLabel(raw === '' ? inner : raw)
      const url = resolve(label)
