{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/** The command: `html`, `outline`, and `defs`, each over the document on standard input,
 * plus an optional definitions file named as a second argument. */

import { readFileSync } from 'node:fs'
import { BlockError, headings, parse, parseDefinitionLine, render, splitLines } from './block.js'

const USAGE = 'usage: cli.js html|outline|defs [<definitions>]'

/** Report one failure the way the specification words it, and stop. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

const argv = process.argv.slice(2)
const mode = argv[0]
const definitionsPath = argv[1]
if (!['html', 'outline', 'defs'].includes(mode) || argv.length < 1 || argv.length > 2) fail(USAGE)

const fileDefinitions = new Map()
if (definitionsPath !== undefined) {
  let text
  try {
    text = readFileSync(definitionsPath, 'utf8')
  } catch {
    fail(`cannot read definitions ${definitionsPath}`)
  }
  const lines = splitLines(text)
  for (let index = 0; index < lines.length; index += 1) {
    const trimmed = lines[index].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const definition = parseDefinitionLine(trimmed)
    if (definition === undefined) fail(`${definitionsPath}: line ${index + 1}: expected [label]: <url>`)
    if (fileDefinitions.has(definition.label)) fail(`${definitionsPath}: line ${index + 1}: label ${definition.label} is defined twice`)
    fileDefinitions.set(definition.label, definition.url)
  }
}

let parsed
try {
  parsed = parse(splitLines(readFileSync(0, 'utf8')), new Set(fileDefinitions.keys()))
} catch (error) {
  if (!(error instanceof BlockError)) throw error
  fail(`line ${error.line}: ${error.message}`)
}

const resolve = (label) => {
  if (parsed.definitions.has(label)) return parsed.definitions.get(label)
  return fileDefinitions.get(label)
}

if (mode === 'html') {
  process.stdout.write(render(parsed.blocks, resolve))
} else if (mode === 'outline') {
  process.stdout.write(headings(parsed.blocks).map(one => `${one.level} ${one.text}\n`).join(''))
} else {
  const entries = [
    ...[...fileDefinitions.entries()].map(([label, url]) => ({ label, url, source: 'file' })),
    ...[...parsed.definitions.entries()].map(([label, url]) => ({ label, url, source: 'document' })),
  ]
  entries.sort((a, b) => (a.label < b.label ? -1 : a.label > b.label ? 1 : 0))
  const lines = entries.map(one => `${one.label} ${one.url} ${one.source}\n`)
  lines.push(`total ${entries.length}\n`)
  process.stdout.write(lines.join(''))
}
"}

